parts=[]; toc=[]; svgs=[]
def p(s): parts.append('<p>'+s+'</p>')
def h(s): parts.append('<h3>'+s+'</h3>')
def note(s): parts.append('<aside>'+s+'</aside>')
def code(s): pass  # The reader requested a visual explanation without code blocks.
def chapter(id,title):
 toc.append((id,title));parts.append(f'<section id="{id}"><h2>{len(toc)}. {title}</h2>')
def end():parts.append('</section>')
def table(head,rows):
 parts.append('<div class="scroll"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>')
def fig(title,nodes,edges,labels=(),width=900,height=290):
 # node: id,x,y,text,kind(optional); edges: source,target,label(optional)
 d={n[0]:n for n in nodes}; a=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} {height}" role="img" aria-label="{E(title)}"><title>{E(title)}</title><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="#64748b"/></marker></defs>']
 for edge in edges:
  u,v=d[edge[0]],d[edge[1]];x,y=u[1:3];xx,yy=v[1:3]
  a.append(f'<path d="M{x} {y+18} L{xx} {yy-20}" stroke="#64748b" stroke-width="2" fill="none" marker-end="url(#arrow)"/>')
  if len(edge)>2:a.append(f'<text x="{(x+xx)/2+12}" y="{(y+yy)/2}" font-size="14" fill="#475569">{E(edge[2])}</text>')
 for n in nodes:
  id,x,y,t=n[:4];kind=n[4] if len(n)>4 else ''; fill={'hot':'#dbeafe','red':'#fee2e2','black':'#1e293b','green':'#dcfce7'}.get(kind,'#fff');fg='#fff' if kind=='black' else '#172033';w=max(54,len(t)*8+22)
  a.append(f'<rect x="{x-w/2}" y="{y-20}" width="{w}" height="40" rx="10" fill="{fill}" stroke="#64748b" stroke-width="1.5"/><text x="{x}" y="{y+5}" text-anchor="middle" font-family="Arial,sans-serif" font-size="16" fill="{fg}">{E(t)}</text>')
 for x,y,t in labels:a.append(f'<text x="{x}" y="{y}" font-family="Arial,sans-serif" font-size="16" fill="#475569">{E(t)}</text>')
 a.append('</svg>');svg=''.join(a).replace('id="arrow"',f'id="arrow{len(svgs)}"').replace('url(#arrow)',f'url(#arrow{len(svgs)})');svgs.append((title,svg));parts.append('<figure>'+svg+'<figcaption>'+str(len(svgs))+'. '+title+'</figcaption></figure>')
def steps(title,items):
 parts.append('<div class="steps"><b>'+title+'</b><ol>'+''.join('<li>'+x+'</li>' for x in items)+'</ol></div>')
def quiz(q,a):parts.append('<details><summary>'+q+'</summary><p>'+a+'</p></details>')
