fig('Склеиваем красных детей с чёрным родителем: получаем 4-узел',[('b',220,55,'20 B','black'),('l',100,155,'10 R','red'),('r',340,155,'30 R','red'),('m',690,105,'10 | 20 | 30','green')],[('b','l'),('b','r')],[(50,250,'NIL-дети опущены; все они чёрные'),(520,250,'Один логический уровень')])
