# Final reading order requested by the reader.
import re
reading_order = ['start', 'base', 'avl', 'rb', 'btree', 'treap', 'implicit',
                 'segment', 'fenwick', 'trie', 'patricia', 'kmp-z-sp', 'practice', 'summary']
exec((P/'content_transitions.py').read_text())
exec((P/'content_operations.py').read_text())
exec((P/'content_kmp.py').read_text())
sections = dict(re.findall(r'<section id="([^"]+)">(.*?)</section>', ''.join(parts), re.S))
for key, addition in visual_additions.items():
    sections[key] += addition
titles = dict(toc)
assert set(reading_order) == set(sections) == set(titles)
toc = [(key, titles[key]) for key in reading_order]
parts = []
for number, key in enumerate(reading_order, 1):
    body = re.sub(r'^<h2>\d+\. ', f'<h2>{number}. ', sections[key], count=1)
    parts.append(f'<section id="{key}">{body}</section>')
figure_number = 0
def renumber_caption(match):
    global figure_number
    figure_number += 1
    return f'<figcaption>{figure_number}. '
content = re.sub(r'<figcaption>\d+\. ', renumber_caption, ''.join(parts))
# Stable anchors and per-operation navigation to a matching process diagram.
content = re.sub(r'<figure>(.*?)<figcaption>(\d+)\. ',
    lambda m: f'<figure id="figure-{m[2]}">{m[1]}<figcaption>{m[2]}. ', content, flags=re.S)
exec((P/'operation_catalog.py').read_text())
coverage = []
def add_operation_index(match):
    key, body = match[1], match[2]
    entries = operation_catalog.get(key, [])
    if not entries: return match[0]
    figures = re.findall(r'<figcaption>(\d+)\. (.*?)</figcaption>', body, re.S)
    rows = []
    for operation, title_fragment in entries:
        candidates = [(num, title) for num, title in figures if title_fragment in title]
        assert candidates, (key, operation, title_fragment)
        number, title = candidates[0]
        rows.append(f'<li><b>{operation}</b> — <a href="#figure-{number}">рисунок {number}</a></li>')
        coverage.append({'chapter':key, 'operation':operation, 'figure':int(number), 'title':title})
    index = '<h3>Операции и схемы процесса</h3><ul>'+''.join(rows)+'</ul>'
    body = re.sub(r'(</h2>)', lambda m: m[0]+index, body, count=1)
    return f'<section id="{key}">{body}</section>'
content = re.sub(r'<section id="([^"]+)">(.*?)</section>', add_operation_index, content, flags=re.S)
content = content.replace('<code>', '').replace('</code>', '')
exec((P/'edit_web_text.py').read_text())
content = improve_content(content)
(P/'operation_coverage.json').write_text(json.dumps(coverage, ensure_ascii=False, indent=2))
exec((P/'export_markdown.py').read_text())
export_markdown(content, toc, P/'structures.md')
parts = [content]
# Exported SVG numbers follow the same order as the printed captions.
svgs = [(title, svg) for svg, title in re.findall(
    r'(<svg\b.*?</svg>)<figcaption>\d+\. (.*?)</figcaption>', content, re.S)]
assert figure_number == len(svgs)

css=(P/'web.css').read_text()
nav=''.join(f'<a class="chapter-link" href="#{key}">{i}. {title}</a>' for i,(key,title) in enumerate(toc,1))
html=(P/'web_template.html').read_text().replace('__STYLE__',css).replace('__NAV__',nav).replace('__BODY__',content).replace('__SCRIPT__',(P/'web.js').read_text())
html = html.replace('__CHAPTERS__', str(len(toc))).replace('__FIGURES__', str(len(svgs)))
(P/'structures.html').write_text(html)
(P/'svg').mkdir(exist_ok=True)
for i,(title,svg) in enumerate(svgs,1):(P/'svg'/f'{i:02}.svg').write_text(svg)
print(json.dumps({'chapters':len(toc),'diagrams':len(svgs),'bytes':len(html.encode()),'words':len(' '.join(parts).split())}))

